// shipping.rs — computes adjusted delivery estimates when carrier delays are reported.
// Carriers occasionally publish a delay window; we add it to the promised date
// before surfacing an ETA to the customer-facing tracker. Keep this pure so the
// chatbot backend and the email notifier can share the same logic.
pub fn adjusted_eta(promised_days: i64, delay_days: Option<i64>) -> i64 {
    promised_days + delay_days.unwrap_or(0)
}
